using Finch
using TensorMarket
using JSON
using SparseArrays

# C = A * B^T. B as generated by make_outer_data.jl is M x K, i.e. already the transposed operand from
# Gustavson's point of view. B^T (K x M) is formed here (untimed) so the MKL kernel is a plain CSR A * B' product.
function outer_mkl(A, B, nt)
    tmpdir = mktempdir(@__DIR__, prefix="experiment_")
    A_path = joinpath(tmpdir, "A.ttx")
    B_path = joinpath(tmpdir, "B.ttx")
    C_path = joinpath(tmpdir, "C.ttx")
    fwrite(A_path, Tensor(Dense(SparseList(Element(0.0))), A)) #TACO matrix market reader can only read real-valued matrices
    fwrite(B_path, Tensor(Dense(SparseList(Element(0.0))), sparse(B'))) 
    mklvars_path = "/opt/intel/oneapi/setvars.sh"
    outer_path = joinpath(@__DIR__, "outer_mkl")
    withenv() do
        cmd = "source $mklvars_path; $outer_path -i $tmpdir -o $tmpdir"
        run(`bash -c $cmd`)
    end
    C = fread(C_path)
    time = JSON.parsefile(joinpath(tmpdir, "measurements.json"))["time"]
    return (;time=time*10^-9, C=C)
end

has_mkl() = isfile(joinpath(@__DIR__, "outer_mkl"))
